#!/usr/bin/env node
/* Genera public/js/local-bundle.js: incorpora i moduli del server come stringhe
 * così LocalCG funziona anche aprendo index.html da file:// (senza XHR/CORS).
 * Rilanciare dopo ogni modifica alla logica in server/. */
const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "..");
const serverDir = path.join(root, "server");

function listDir(dir, rel) {
  return fs
    .readdirSync(path.join(serverDir, rel), { withFileTypes: true })
    .filter((e) => e.isFile() && e.name.endsWith(".js") && !e.name.endsWith(".test.js"))
    .map((e) => (rel ? rel + "/" : "") + e.name)
    .sort();
}

const files = [...listDir(serverDir, ""), ...listDir(serverDir, "games")]
  .filter((f) => f !== "index.js"); // entry del server Node: non serve nel browser

if (!files.includes("cards.js") || !files.includes("rooms.js")) {
  console.error("build-local-bundle: file principali mancanti in server/");
  process.exit(1);
}

const bundle = {};
for (const f of files) {
  bundle[f] = fs.readFileSync(path.join(serverDir, f), "utf8");
}

const out =
  "/* GENERATED by scripts/build-local-bundle.js — non modificare a mano.\n" +
  " * Rigenerare con: npm run build:local */\n" +
  "(function (root) {\n" +
  '  "use strict";\n' +
  "  root.__LOCALCG_BUNDLE__ = " + JSON.stringify(bundle, null, 2) + ";\n" +
  "})(typeof self !== \"undefined\" ? self : typeof globalThis !== \"undefined\" ? globalThis : this);\n";

const outPath = path.join(root, "public", "js", "local-bundle.js");
fs.writeFileSync(outPath, out);

const kb = (Buffer.byteLength(out) / 1024).toFixed(1);
console.log("build-local-bundle: " + files.length + " moduli → public/js/local-bundle.js (" + kb + " KB)");
